css:
.p3-stage { border: 2px solid var(--ink); border-radius: 12px; overflow: hidden; background: #04060f; }
.p3-home { position: absolute; right: 14px; top: 12px; z-index: 3; font-size: 19px !important; padding: 8px 14px !important; }
.p3-plate { position: absolute; left: 0; top: 0; z-index: 1; pointer-events: none; font: 800 15px var(--f-body); color: #fffbe6; text-shadow: 0 0 4px #081028, 0 0 8px #081028, 0 1px 2px #000; white-space: nowrap; }
.p3-plate.off, .p3-pin.off { visibility: hidden; }
.p3-pin { position: absolute; left: 0; top: 0; z-index: 2; width: 34px; height: 34px; padding: 0; border-radius: 50%; border: 3px solid #1d2433; background: #ffd84d; color: #1d2433; font: 800 17px var(--f-body); cursor: grab; touch-action: none; box-shadow: 0 2px 6px rgba(0,0,0,.5); }
.p3-pin.sel { background: #fff; box-shadow: 0 0 0 4px #ffd84d, 0 2px 6px rgba(0,0,0,.5); }
.p3-pin.hot { animation: p3-hot .7s ease-in-out infinite alternate; }
.p3-pin.done { background: var(--good-soft); }
@keyframes p3-hot { to { box-shadow: 0 0 0 10px rgba(255,216,77,.35), 0 2px 6px rgba(0,0,0,.5); } }
.p3-pin:focus-visible { outline: 4px solid var(--accent); outline-offset: 2px; }
.p3-key { position: absolute; left: 14px; bottom: 12px; z-index: 2; display: flex; gap: 12px; padding: 6px 12px; border-radius: 10px; background: rgba(10,14,32,.8); border: 2px solid #5a6a90; color: #fbfcf9; font: 700 15px var(--f-body); pointer-events: none; }
.p3-key i { display: inline-block; width: 20px; height: 5px; border-radius: 3px; background: var(--c); vertical-align: middle; margin-right: 5px; }
.p3-key i.ar { width: 18px; height: 3px; background: #fff8d8; position: relative; }
.p3-key i.ar::after { content: ''; position: absolute; right: -6px; top: -4px; border-left: 7px solid #fff8d8; border-top: 5.5px solid transparent; border-bottom: 5.5px solid transparent; }
.p3-out { margin: 0; font-size: 20px; line-height: 1.5; background: #fffbe6; border: 2px solid var(--accent); border-radius: 12px; padding: 8px 14px; min-height: 3.2em; }
.p3-ok { color: var(--good); font-weight: 800; }
.p3-bins { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; }
.p3-bin { display: flex; flex-direction: column; align-items: stretch; gap: 2px; min-height: 120px; padding: 8px; border: 2.5px dashed var(--ink-3); border-radius: 12px; background: var(--paper-2); cursor: pointer; text-align: center; font: inherit; color: var(--ink); }
.p3-bin[data-k="div"] b { color: #d23a2c; } .p3-bin[data-k="tf"] b { color: #1f9a58; } .p3-bin[data-k="conv"] b { color: #1f7fd6; }
.p3-bin b { font: 800 22px var(--f-display); }
.p3-bin small { font-size: 16px; color: var(--ink-2); }
.p3-bin.over { border-style: solid; border-color: var(--ink); background: color-mix(in srgb, var(--hl) 45%, #fff); }
.p3-bin.ok { animation: p3-ok .5s ease; } .p3-bin.no { animation: p3-no .4s ease; }
@keyframes p3-ok { 40% { background: var(--good-soft); transform: scale(1.04); } }
@keyframes p3-no { 25% { transform: translateX(-6px); background: #ffe1dc; } 75% { transform: translateX(6px); } }
.p3-got { display: flex; flex-direction: column; gap: 4px; margin-top: 4px; }
.p3-chip { font: 700 15px/1.25 var(--f-body); background: #fff; border: 2px solid var(--ink); border-radius: 8px; padding: 2px 4px; }
.p3-ghost { position: fixed; z-index: 99; pointer-events: none; translate: -50% -130%; font: 800 18px var(--f-body); background: #ffd84d; color: #1d2433; border: 2px solid #1d2433; border-radius: 999px; padding: 4px 12px; box-shadow: 0 4px 10px rgba(0,0,0,.3); }

